#### LRU 缓存池
![[Pasted image 20260530185058.png]]
```cpp
struct Node {
	Node *prev, *next;
	int	  key, value;
	Node(int k = 0, int v = 0)
		: key(k)
		, value(v) {}
};

class LRUCache {
  private:
	Node*					  dummy;
	int						  cap;
	unordered_map<int, Node*> key_to_node_;

	Node* get_node(int key) {
		if(key_to_node_.contains(key)) {
			auto update_node = key_to_node_[key];
			remove_node(update_node);
			push_front(update_node);
			return key_to_node_[key];
		}
		return nullptr;
	}

	void push_front(Node* n) {
		n->prev			  = dummy;
		n->next			  = dummy->next;
		dummy->next->prev = n;
		dummy->prev->next = n;
	}

	void remove_node(Node* n) {
		n->next->prev = n->prev;
		n->prev->next = n->next;
	}

  public:
	LRUCache(int capacity) : cap(capacity), dummy(new Node()){
		dummy->next = dummy;
		dummy->prev = dummy;
    }

    int get(int key) {
        auto node = get_node(key);
        return node == nullptr? -1 : node->value;
    }

    void put(int key, int value) {
		auto node = get_node(key);
		if (node != nullptr) {
		    node->value = value;
		    return;
		}
		Node* new_node = new Node(key, value); // add record
		key_to_node_[key] = new_node;
		push_front(new_node);
		if (key_to_node_.size() > capacity_) {
		    auto back_node = dummy->prev;
		    key_to_node_.erase(back_node->key);  // remove record
		    remove(back_node);  // remove entity
		    delete back_node;
		}
    }
};
```
- 设计和构建一个“最近最少使用”缓存，该缓存会删除最近最少使用的项目（超过容量时）
- 查找和插入新值的复杂度都应该是O(1)
- get_node 用来获取一个节点值，这个**获取操作会更新"谁是最近使用的"这一特性**，`key_to_node` **仅仅用来记录一个 key 的节点对应什么，只做一个查询作用**，真正让数据动态更新的是环形链表
- 由 LRU 缓存池设计可知，get 和 set 都会更新"谁是最近使用的"，get 不会更新值，而 set 会更新value，如果 `key_to_node` 中没有对应值还会更新 key

